// Generated by scripts/generate-locales.mjs; edit the canonical content sources.
export default {"heading":"삶, 활동과 유산","introduction":"대학 교육에서 공공행정, 정책 연구와 전문기관 설립에 이르기까지, ICUE 설립자의 삶과 기여를 여덟 장으로 살펴봅니다.","readerHint":"원하는 장을 열거나 계속 버튼으로 차례대로 읽어 보세요.","back":"이전","next":"계속","complete":"읽기 마치기","completed":"읽기 완료","counter":"{total}장 중 {current}장","sourceHref":"https://nguoidothi.net.vn/nghi-ve-mot-nguoi-cong-hien-21097.html","source":"추모 글 · 2019.11.30","photoEvents":{"2017":"VTV1 텔레비전 인터뷰","2018":"편집 동료들과의 회의"},"chapters":[{"id":"life","title":"생애와 고향","period":"1931–2018","heading":"베트남 도시 발전과 함께한 삶","paragraphs":["Phạm Sỹ Liêm 박사는 1931년 응에안성 지엔쩌우현 지엔타인에서 태어났습니다. 토목공학자이자 학자, 공공행정가로서 대학 교육, 고위 공직, 과학 연구와 전문기관 설립에 폭넓게 참여했습니다.","그의 활동은 주거, 토지, 공공 인프라, 도시계획과 거버넌스라는 도시생활의 기반에 지속적으로 관심을 기울였습니다. 다양한 직책에서 전문 지식과 제도 개혁이 발전에 어떻게 기여할 수 있는지 탐구했습니다.","2018년 11월 30일 87세로 세상을 떠났으며, 베트남 전통 나이로는 88세였습니다. 공학 교육, 공직, 독립적 정책 연구와 기관 설립을 연결한 그의 유산은 ICUE를 비롯해 그가 남긴 조직들을 통해 이어지고 있습니다."],"photoEvents":[]},{"id":"education","title":"교육과 공학 인재 양성","period":"1958–1963","heading":"철근콘크리트 공학 교육의 기초를 마련하다","paragraphs":["1950~1960년대에 토목공학을 가르치며 하노이 과학기술대학교의 철근콘크리트 공학 교육 정착에 기여했습니다. 대학 건설학부의 역사 자료에는 1958–1959학년도에 해당 과목을 도입하는 데 참여한 기록이 남아 있습니다.","1959년 10월에는 철근콘크리트 부문 초대 책임자로 임명되었습니다. 교육과 학문 조직을 함께 발전시킨 경력의 초기 이정표였습니다.","1963년 소련에서 대학원 과정을 시작했고, 이후에도 학문 분야의 지도적 역할을 이어갔습니다. 교육과 공학 연구 경험은 훗날 공공행정과 도시정책 활동의 토대가 되었습니다."],"photoEvents":[]},{"id":"public-service","title":"공직과 전문단체 활동","period":"1982년부터","heading":"공공행정과 전문 공동체의 성장","paragraphs":["공직에서는 건설부 차관과 하노이 인민위원회 부위원장을 역임했습니다. 이러한 역할은 그의 공학적 배경을 건설, 인프라와 도시 발전의 실제 행정 과제에 연결했습니다.","1982년부터 베트남 토목공학협회연합회 초대 회장으로 첫 세 임기를 이끌었고, 이후에는 부회장으로 활동을 이어갔습니다.","그의 기여는 직책에만 머물지 않았습니다. 수십 년에 걸쳐 연합회의 조직 체계와 연구 활동, 전문적 영향력을 발전시키는 데 힘썼습니다. 지속 가능한 전문기관을 세운 일은 동료들이 기억하는 중요한 업적 중 하나였습니다."],"photoEvents":[]},{"id":"institutes","title":"연구기관 설립","period":"1999 · 2013","heading":"도시 연구와 정책 자문을 위한 두 기관","paragraphs":["1990~2000년대에는 도시 거버넌스, 인프라와 건설정책으로 연구 범위를 넓혔습니다. 1999년 도시연구·인프라개발연구소를 설립해 해당 분야 연구를 위한 조직적 기반을 마련했습니다.","2013년에는 ICUE를 설립하고 초대 원장을 맡았습니다. 연구를 정책 자문과 발전 현장의 과제에 연결하는 기관을 만들려는 활동을 이어간 것입니다.","두 연구기관은 도시계획, 건설경제와 인프라에 대한 오랜 관심을 보여 줍니다. ICUE에 남긴 설립 정신은 공학 지식, 공공행정 경험과 독립적 탐구의 결합에 있습니다."],"photoEvents":[]},{"id":"policy","title":"도시정책과 공론장","period":"2012–2017","heading":"토지, 계획과 제도에 대한 구체적인 기여","paragraphs":["저서, 연구사업, 학술회의와 인터뷰를 통해 주거, 토지관리, 공공 인프라와 도시 거버넌스를 다뤘습니다. 계획과 정책 집행의 문제점을 공개적으로 비판하며 전문적 토론에도 참여했습니다.","2012년에는 VCCI를 통해 토지법 초안에 대한 상세한 비판 의견을 제출했습니다. 토지 취득, 재산권과 투명성을 다루며 제도적 규칙이 발전과 일상생활에 미치는 영향에 주목했습니다.","2016–2017년에는 계획법 관련 공개 논의에 참여해 국가계획의 조정 강화와 제도 개혁을 주장했습니다. 이러한 활동은 추모 글뿐 아니라 실제 정책 의견 제출 기록으로도 남아 있습니다.","2017년에는 VTV1 텔레비전 인터뷰에 출연했습니다. 아래 자료 사진은 그 인터뷰의 한 장면입니다."],"photoEvents":["2017"]},{"id":"editorial","title":"Người Đô Thị와 편집 활동","period":"2006–2018","heading":"도시와 삶의 질을 논의하는 공간","paragraphs":["2006년 도시 문제를 다루는 잡지 Người Đô Thị를 공동 창간하고 전문 자문위원회 위원장을 맡았습니다.","잡지는 도시정책과 삶의 질을 논의하는 장이 되었습니다. 연구와 전문단체 활동에 더해, 도시의 전문적 질문을 폭넓은 공적 대화로 이어가는 공간이었습니다.","그는 세상을 떠날 때까지 잡지의 전문 활동에 참여했습니다. 2018년 사진은 편집 동료들과 함께한 회의를 담고 있으며, 기록으로 남은 생애 마지막 시기의 편집 회의 중 하나입니다."],"photoEvents":["2018"]},{"id":"scholarship","title":"마지막 해까지 이어진 연구","period":"2018년 9월","heading":"87세에 출간한 신제도경제학","paragraphs":["2017–2018년에도 고령에도 불구하고 연구와 전문기관 자문을 계속했습니다. 고위 공직을 거친 뒤에도 학문적 호기심을 잃지 않았습니다.","2018년 9월 마지막 주요 학술 저서 Tân kinh tế học thể chế(신제도경제학)를 출간했습니다. 제도와 경제 발전의 관계를 탐구하며 거버넌스와 개혁에 대한 오랜 관심을 이어간 책입니다.","87세에 출간한 이 책은 베트남의 연구·정책 문서와 함께 200편 이상의 해외 자료를 참고한 것으로 전해집니다. 생애 마지막 해까지 지속한 학습과 지적 노동을 보여 줍니다."],"photoEvents":[]},{"id":"legacy","title":"동료들이 기억하는 사람","period":"2019년 추모행사의 회고","heading":"청렴함, 지적 깊이와 뛰어난 업무 역량","paragraphs":["동료들은 고위 공직에 오른 뒤에도 배움을 이어간 학자로 그를 기억했습니다. 생애를 다룬 글들에는 영어, 프랑스어, 러시아어와 중국어의 네 외국어를 구사했다는 내용이 전해집니다.","2019년 추모행사에서 연합회 회장 Trần Ngọc Hùng은 해외에 나갈 때면 서점을 찾던 그의 모습을 회고했습니다. 그는 방대한 개인 서재를 갖추고 여러 분야의 책을 읽었으며, 무협소설도 즐겼습니다.","학술원 회원 Phạm Hồng Giang은 그의 유산을 개인적 청렴함, 지적 깊이와 탁월한 업무 역량이라는 세 가지 특성으로 설명했습니다. 이는 동료들의 평가와 기억으로, 직책과 저서 뒤에 있는 인간적 면모를 보여 줍니다.","2019년 글 Nghĩ về một người cống hiến는 수십 년간 함께 일한 사람의 회고를 통해 더욱 가까운 이야기를 전합니다. ICUE에 남은 그의 유산은 공학 교육, 공직, 독립적 연구, 기관 설립과 평생의 학문 활동을 함께 아우릅니다."],"photoEvents":[]}],"nguoiDoThi":"https://nguoidothi.net.vn/","remembrance":"https://nguoidothi.net.vn/nghi-ve-mot-nguoi-cong-hien-21097.html"}
